-- Fantasy Friends executable migration 20261115000018_live_match_market_workflow
-- Generated by scripts/promote-migrations.mjs from supabase/design/migrations/018_live_match_market_workflow.sql
-- Do not edit by hand: the guard re-derives this file and fails on drift.

-- Phase 4 forward-only Live Match integration.
--
-- Market players are league-scoped player_profiles already; the old match guard
-- only accepted real_team_players registrations or a separate leader-created
-- temporary authorization. That made published Market players unusable unless
-- duplicated through a roster workflow. Match selection now binds directly to
-- an active same-league League Market row, without creating profiles or checking
-- fantasy squad ownership. The existing revision uniqueness constraint keeps a
-- player from appearing on both sides.

begin;

alter table public.real_match_lineup_players
  drop constraint real_match_lineup_players_eligibility_kind_check,
  add constraint real_match_lineup_players_eligibility_kind_check
    check (eligibility_kind in ('registered', 'temporary', 'market'));

create or replace function ff_private.guard_revision_child() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare r uuid; l uuid; match_row public.real_matches%rowtype; revision_row public.match_revisions%rowtype;
  lineup_team uuid; n integer; limit_count integer;
begin
 if tg_op='DELETE' then r:=old.revision_id; l:=old.league_id; else r:=new.revision_id; l:=new.league_id; end if;
 select m.* into match_row from public.match_revisions v join public.real_matches m on m.league_id=v.league_id and m.id=v.match_id
   where v.league_id=l and v.id=r for update of m;
 if not found then raise exception 'unknown revision' using errcode='23503'; end if;
 select * into revision_row from public.match_revisions where league_id=l and id=r for update;
 if exists(select 1 from public.match_submissions s where s.league_id=l and s.revision_id=r) then
   raise exception 'submitted revision content is immutable' using errcode='23514';
 end if;
 if tg_op='UPDATE' and (old.revision_id,old.league_id) is distinct from (new.revision_id,new.league_id) then
   raise exception 'cannot move revision content' using errcode='23514'; end if;
 if tg_op='DELETE' then return old; end if;
 if tg_table_name='real_match_lineups' then
   if tg_op='UPDATE' and (new.id,new.league_id,new.match_id,new.revision_id,new.team_id) is distinct from (old.id,old.league_id,old.match_id,old.revision_id,old.team_id) then
     raise exception 'lineup identity cannot be changed' using errcode='23514'; end if;
   if new.match_id<>match_row.id or new.team_id not in (match_row.team_a_id,match_row.team_b_id) then
     raise exception 'lineup team must be a match side' using errcode='23514'; end if;
 elsif tg_table_name='real_match_lineup_players' then
   select team_id into lineup_team from public.real_match_lineups where league_id=l and revision_id=r and id=new.lineup_id;
   if not found or lineup_team not in (match_row.team_a_id,match_row.team_b_id) then
     raise exception 'invalid lineup side' using errcode='23514'; end if;
   if new.eligibility_kind='registered' and not exists(
     select 1 from public.real_team_players p where p.league_id=l and p.team_id=lineup_team and p.player_id=new.player_id
       and p.valid_from<=match_row.starts_at and (p.valid_until is null or p.valid_until>match_row.starts_at)
   ) then raise exception 'player not registered for match side at kickoff' using errcode='23514'; end if;
   if new.eligibility_kind='temporary' and not exists(
     select 1 from public.temporary_participant_authorizations a where a.league_id=l and a.match_id=match_row.id
       and a.team_id=lineup_team and a.player_id=new.player_id
   ) then raise exception 'missing temporary authorization' using errcode='23514'; end if;
   if new.eligibility_kind='market' and not exists(
     select 1 from public.league_players p where p.league_id=l and p.player_id=new.player_id and p.active
   ) then raise exception 'player is not in this league market' using errcode='23514'; end if;
   limit_count:=case new.selection when 'starter' then match_row.starters_per_side else match_row.max_substitutes end;
   select count(*) into n from public.real_match_lineup_players p where p.league_id=l and p.lineup_id=new.lineup_id
     and p.selection=new.selection and (tg_op<>'UPDATE' or p.id<>old.id);
   if n>=limit_count then raise exception 'lineup exceeds format limit' using errcode='23514'; end if;
 end if;
 return new;
end $$;

create or replace function ff_private.validate_lineups(p_league uuid,p_revision uuid) returns void
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare m public.real_matches%rowtype; sides integer;
begin
 select m0.* into m from public.match_revisions r join public.real_matches m0 on m0.league_id=r.league_id and m0.id=r.match_id
 where r.league_id=p_league and r.id=p_revision for update of m0;
 if not found then raise exception 'revision not found' using errcode='23503'; end if;
 select count(*) into sides from public.real_match_lineups l where l.league_id=p_league and l.revision_id=p_revision
   and l.team_id in (m.team_a_id,m.team_b_id);
 if sides<>2 then raise exception 'both match sides required' using errcode='23514'; end if;
 if exists(select 1 from public.real_match_lineups l where l.league_id=p_league and l.revision_id=p_revision and
    (select count(*) from public.real_match_lineup_players p where p.lineup_id=l.id and p.selection='starter')<>m.starters_per_side)
 then raise exception 'each side needs expected starters' using errcode='23514'; end if;
 if exists(select 1 from public.real_match_lineups l where l.league_id=p_league and l.revision_id=p_revision and
    (select count(*) from public.real_match_lineup_players p where p.lineup_id=l.id and p.selection='substitute')>m.max_substitutes)
 then raise exception 'too many substitutes' using errcode='23514'; end if;
 if exists(select 1 from public.real_match_lineup_players p join public.real_match_lineups l on l.league_id=p.league_id and l.id=p.lineup_id
   where p.league_id=p_league and p.revision_id=p_revision and
   ((p.eligibility_kind='registered' and not exists(select 1 from public.real_team_players rp where rp.league_id=p.league_id and rp.team_id=l.team_id and rp.player_id=p.player_id and rp.valid_from<=m.starts_at and (rp.valid_until is null or rp.valid_until>m.starts_at)))
   or (p.eligibility_kind='temporary' and not exists(select 1 from public.temporary_participant_authorizations a where a.league_id=p.league_id and a.match_id=m.id and a.team_id=l.team_id and a.player_id=p.player_id))
   or (p.eligibility_kind='market' and not exists(select 1 from public.league_players mp where mp.league_id=p.league_id and mp.player_id=p.player_id and mp.active))))
 then raise exception 'ineligible player' using errcode='23514'; end if;
end $$;

-- Keep the client-callable assignment path Market-only. Historical registered or
-- temporarily-authorized lineup rows may still be copied by the trusted result /
-- correction routines above this API layer, but organizers cannot add new rows
-- through those legacy eligibility modes.
create or replace function public.ff_match_set_lineup(
  p_league uuid, p_revision uuid, p_team uuid, p_players jsonb)
returns jsonb
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare r public.match_revisions; v_lineup public.real_match_lineups; item jsonb;
begin
  select * into r from public.match_revisions where league_id=p_league and id=p_revision;
  if not found then raise exception 'revision not found' using errcode='42501'; end if;
  if not (ff_private.is_leader(p_league) or ff_private.is_match_organizer(p_league,r.match_id)) then
    raise exception 'not the organizer of this match' using errcode='42501';
  end if;
  if r.state<>'draft' then raise exception 'revision is no longer editable' using errcode='23514'; end if;
  if p_players is null or jsonb_typeof(p_players)<>'array' or jsonb_array_length(p_players)=0 then
    raise exception 'a lineup needs at least one player' using errcode='23514';
  end if;
  if exists(select 1 from jsonb_array_elements(p_players) as row_data(entry) where coalesce(entry->>'eligibility_kind','market')<>'market') then
    raise exception 'new lineup assignments must come from this league market' using errcode='23514';
  end if;
  select * into v_lineup from public.real_match_lineups where league_id=p_league and revision_id=p_revision and team_id=p_team;
  if not found then
    insert into public.real_match_lineups(league_id,match_id,revision_id,team_id)
    values(p_league,r.match_id,p_revision,p_team) returning * into v_lineup;
  else
    delete from public.real_match_lineup_players where league_id=p_league and revision_id=p_revision and lineup_id=v_lineup.id;
  end if;
  for item in select * from jsonb_array_elements(p_players) loop
    insert into public.real_match_lineup_players(league_id,revision_id,lineup_id,player_id,selection,actual_position,eligibility_kind,eligibility_evidence)
    values(p_league,p_revision,v_lineup.id,(item->>'player_id')::uuid,item->>'selection',item->>'actual_position','market',
      coalesce(item->'eligibility_evidence','{}'::jsonb));
  end loop;
  perform ff_private.audit(p_league,'lineup_draft_set','match',r.match_id,
    jsonb_build_object('revision',p_revision,'team',p_team,'players',jsonb_array_length(p_players)));
  return jsonb_build_object('lineup_id',v_lineup.id,'players',jsonb_array_length(p_players));
end $$;

-- Tighten persisted scheduling fields without changing the RPC signature or ACL.
create or replace function public.ff_match_create(
  p_league uuid, p_gameweek uuid, p_team_a uuid, p_team_b uuid, p_organizer uuid,
  p_starts_at timestamptz, p_venue text, p_starters_per_side integer default 7,
  p_max_substitutes integer default 5)
returns jsonb
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare v public.real_matches;
begin
  perform ff_private.require_leader(p_league);
  if p_team_a is null or p_team_b is null or p_team_a = p_team_b then
    raise exception 'choose two different teams' using errcode='23514';
  end if;
  if not exists (select 1 from public.match_organizers o join public.league_members lm
      on lm.league_id=o.league_id and lm.user_id=o.user_id
      where o.league_id=p_league and o.user_id=p_organizer and lm.status='active') then
    raise exception 'organizer must be an active appointed match organizer' using errcode='23514';
  end if;
  if not exists (select 1 from public.gameweeks where league_id=p_league and id=p_gameweek) then
    raise exception 'gameweek not found' using errcode='23514';
  end if;
  if not exists (select 1 from public.real_football_teams where league_id=p_league and id=p_team_a and active)
     or not exists (select 1 from public.real_football_teams where league_id=p_league and id=p_team_b and active) then
    raise exception 'both active teams must belong to this league' using errcode='42501';
  end if;
  if p_starts_at is null then raise exception 'a match needs a kick-off time' using errcode='23514'; end if;
  if p_venue is null or length(btrim(p_venue))=0 or length(btrim(p_venue))>200 then
    raise exception 'venue is required and must be at most 200 characters' using errcode='23514';
  end if;
  if coalesce(p_starters_per_side,0) not between 1 and 11 or coalesce(p_max_substitutes,-1) not between 0 and 30 then
    raise exception 'starters must be 1–11 and substitutes 0–30' using errcode='23514';
  end if;
  insert into public.real_matches(league_id,gameweek_id,team_a_id,team_b_id,organizer_id,starts_at,venue,starters_per_side,max_substitutes)
  values(p_league,p_gameweek,p_team_a,p_team_b,p_organizer,p_starts_at,btrim(p_venue),p_starters_per_side,p_max_substitutes)
  returning * into v;
  perform ff_private.audit(p_league,'match_created','match',v.id,
    jsonb_build_object('gameweek_id',p_gameweek,'team_a',p_team_a,'team_b',p_team_b));
  return jsonb_build_object('id',v.id,'starts_at',v.starts_at,'organizer_id',p_organizer);
end $$;

-- Expose append-only workflow history and both lineups through the existing,
-- member-scoped read RPC. No direct table access or new EXECUTE grant is added.
create or replace function public.ff_matches(p_league uuid)
returns jsonb
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
  perform ff_private.require_member(p_league);
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', m.id, 'gameweek_id', m.gameweek_id, 'starts_at', m.starts_at, 'venue', m.venue,
      'team_a_id', m.team_a_id, 'team_a', ta.name, 'team_b_id', m.team_b_id, 'team_b', tb.name,
      'organizer_id', m.organizer_id, 'starters_per_side', m.starters_per_side,
      'max_substitutes', m.max_substitutes,
      'revision_id', r.id, 'revision_version', r.version, 'revision_state', r.state,
      'team_a_score', r.team_a_score, 'team_b_score', r.team_b_score,
      'events', coalesce((select jsonb_agg(jsonb_build_object(
                    'id', e.id, 'type', e.event_type, 'minute', e.minute, 'quantity', e.quantity,
                    'player_id', e.player_id,
                    'player_name', (select pp.display_name from public.real_match_lineup_players lp
                                     join public.player_profiles pp on pp.league_id = lp.league_id and pp.id = lp.player_id
                                    where lp.league_id = e.league_id and lp.revision_id = e.revision_id and lp.player_id = e.player_id)
                  ) order by e.minute nulls last)
                  from public.match_events e where e.league_id = m.league_id and e.revision_id = r.id), '[]'::jsonb),
      'history', coalesce((select jsonb_agg(jsonb_build_object(
        'revision_id',v.id,'version',v.version,'state',v.state,'team_a_score',v.team_a_score,'team_b_score',v.team_b_score,
        'correction',(select jsonb_build_object('reason',c.reason,'actor_id',c.actor_id,'created_at',c.created_at) from public.match_corrections c where c.league_id=v.league_id and c.draft_revision_id=v.id),
        'events',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'type',e.event_type,'minute',e.minute,'quantity',e.quantity,'player_id',e.player_id,'player_name',(select pp.display_name from public.player_profiles pp where pp.league_id=e.league_id and pp.id=e.player_id),'related_player_id',e.related_player_id) order by e.minute nulls last)
          from public.match_events e where e.league_id=v.league_id and e.revision_id=v.id),'[]'::jsonb),
        'submissions',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'kind',s.kind,'submitted_by',s.submitted_by,'submitted_at',s.submitted_at,
          'approval', (select jsonb_build_object('id',a.id,'decision',a.decision,'reason',a.reason,'reviewed_by',a.reviewed_by,'reviewed_at',a.reviewed_at)
            from public.match_approvals a where a.league_id=s.league_id and a.submission_id=s.id)) order by s.submitted_at)
          from public.match_submissions s where s.league_id=v.league_id and s.revision_id=v.id),'[]'::jsonb),
        'lineups',coalesce((select jsonb_agg(jsonb_build_object('team_id',ln.team_id,'players',coalesce((select jsonb_agg(jsonb_build_object(
          'player_id',lp.player_id,'name',pp.display_name,'selection',lp.selection,'actual_position',lp.actual_position)
          order by lp.selection,pp.display_name) from public.real_match_lineup_players lp join public.player_profiles pp
          on pp.league_id=lp.league_id and pp.id=lp.player_id where lp.league_id=ln.league_id and lp.lineup_id=ln.id),'[]'::jsonb)) order by ln.team_id)
          from public.real_match_lineups ln where ln.league_id=v.league_id and ln.revision_id=v.id),'[]'::jsonb)
      ) order by v.version desc) from public.match_revisions v where v.league_id=m.league_id and v.match_id=m.id),'[]'::jsonb)
    ) order by m.starts_at desc)
    from public.real_matches m
    join public.real_football_teams ta on ta.league_id = m.league_id and ta.id = m.team_a_id
    join public.real_football_teams tb on tb.league_id = m.league_id and tb.id = m.team_b_id
    left join lateral (select * from public.match_revisions v where v.league_id = m.league_id and v.match_id = m.id order by v.version desc limit 1) r on true
    where m.league_id = p_league
  ), '[]'::jsonb);
end $$;

commit;
